package com.bautruc.ecommerce.payment.application;
import java.util.*;import java.util.stream.Collectors;
import com.bautruc.ecommerce.common.exception.ResourceNotFoundException;import com.bautruc.ecommerce.payment.domain.*;import com.bautruc.ecommerce.payment.infrastructure.PaymentJpaRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentQueryService implements PaymentQueryPort{private final PaymentJpaRepository payments;public PaymentQueryService(PaymentJpaRepository p){payments=p;}@Transactional(readOnly=true)public Payment required(Long id){return payments.findById(id).orElseThrow(()->new ResourceNotFoundException(PaymentErrorCodes.PAYMENT_NOT_FOUND,"Payment not found."));}@Transactional(readOnly=true)public Payment forOrder(Long orderId){return payments.findByOrderId(orderId).orElseThrow(()->new ResourceNotFoundException(PaymentErrorCodes.PAYMENT_NOT_FOUND,"Payment not found."));}@Override public PaymentOrderSnapshot forOrderSnapshot(Long orderId){Payment p=forOrder(orderId);return new PaymentOrderSnapshot(p.getId(),p.getStatus(),p.getAmount(),p.getCheckoutUrl(),p.getQrCode(),p.getExpiresAt());}@Override public PaymentStatus statusForOrder(Long orderId){return forOrder(orderId).getStatus();}@Override public PaymentStatus statusForOrderForUpdate(Long orderId){return payments.findByOrderIdForUpdate(orderId).orElseThrow(()->new ResourceNotFoundException(PaymentErrorCodes.PAYMENT_NOT_FOUND,"Payment not found.")).getStatus();}@Override public Map<Long,PaymentStatus> statusesForOrders(Collection<Long> ids){return payments.findByOrderIdIn(ids).stream().collect(Collectors.toMap(Payment::getOrderId,Payment::getStatus));}}
